package com.ustp.tracker;

/** Built-in copy of the USTP logo so it always shows, even if images/logo.png is missing. */
final class LogoData {
    private LogoData() {}

    static final String[] PARTS = {
        "",
        "",
        ""
    };

    static byte[] bytes() {
        return java.util.Base64.getDecoder().decode(String.join("", PARTS));
    }
}
